-- Enable Row Level Security on the notes table
alter table public.notes enable row level security;

-- Create a function to check if the current user is the owner of the note
create or replace function public.is_note_owner(note_id bigint) returns boolean as $$
  select (auth.uid() = any ((
    select user_id
    from public.notes
    where id = note_id
  )));
$$ language sql stable;

-- Create a function to check if the current user is authenticated
create or replace function public.is_authenticated() returns boolean as $$
  select auth.jwt()->>'sub' is not null and auth.jwt()->>'sub' != 'service_role';
$$ language sql stable;

-- Create a policy allowing authenticated users to read their own notes
create policy "Users can read their own notes"
  on public.notes for select
  using (auth.uid() = user_id or not is_authenticated());

-- Create a policy allowing authenticated users to read public notes
create policy "Users can read public notes"
  on public.notes for select
  using (is_public = true and is_authenticated());

-- Create a policy allowing authenticated users to insert notes as themselves
create policy "Users can create notes as themselves"
  on public.notes for insert
  with check (auth.uid() = user_id);

-- Create a policy allowing authenticated users to update their own notes
create policy "Users can update their own notes"
  on public.notes for update
  using (auth.uid() = user_id);

-- Create a policy allowing authenticated users to delete their own notes
create policy "Users can delete their own notes"
  on public.notes for delete
  using (auth.uid() = user_id);

-- Grant full access to the service_role (bypasses RLS)
grant all on public.notes to service_role;

-- Revoke public access to ensure anonymous users cannot read, create, edit, or delete notes
revoke all on public.notes from anon;
revoke all on public.notes from authenticated;
revoke all on public.notes from authenticated in schema public;
