-- Enable Row Level Security on all tables
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- R9: Service role bypasses RLS for internal operations
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;

-- R8: Anonymous users cannot see or change anything
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;

-- R1, R2, R3, R4, R5, R6: Custom policies based on team membership and roles
-- Helper function to check if user is a member of a team with a specific role
create function public.is_member_of_team(p_team_id bigint, p_role text)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id
    and user_id = auth.uid()
    and role = p_role
  );
$$;

-- R1: Users can see the teams they belong to (either as viewer or editor)
create policy "Users can view teams they belong to"
on public.teams
for select
using (
  exists (
    select 1 from public.team_members
    where team_id = public.teams.id
    and user_id = auth.uid()
  )
);

-- R7: Teams and memberships cannot be created, changed or removed by users of the app
create policy "Prevent users from creating teams"
on public.teams
for insert
with check (false);

create policy "Prevent users from updating teams"
on public.teams
for update
using (false);

create policy "Prevent users from deleting teams"
on public.teams
for delete
using (false);

create policy "Prevent users from creating team memberships"
on public.team_members
for insert
with check (false);

create policy "Prevent users from updating team memberships"
on public.team_members
for update
using (false);

create policy "Prevent users from deleting team memberships"
on public.team_members
for delete
using (false);

-- R2: Users can see their own membership rows, but not others'
create policy "Users can view their own team memberships"
on public.team_members
for select
using (auth.uid() = user_id);

-- R3: Members of a team can read the team's documents, except deleted documents
create policy "Members can read non-deleted team documents"
on public.documents
for select
using (
  public.is_member_of_team(team_id, 'viewer') OR
  public.is_member_of_team(team_id, 'editor')
  AND deleted_at IS NULL
);

-- R4: Editors can create documents in their teams. Viewers cannot create documents.
create policy "Editors can create documents in their teams"
on public.documents
for insert
with check (
  public.is_member_of_team(team_id, 'editor')
  AND created_by = auth.uid()
);

-- R5: Editors can edit any document in their teams. After an edit, the document must still belong to a team where the user is an editor.
-- Note: Since R3 restricts viewing to team members, we assume only team members can edit.
-- The condition ensures the user is an editor in the team owning the document.
create policy "Editors can update documents in their teams"
on public.documents
for update
using (
  public.is_member_of_team(team_id, 'editor')
  AND (
    -- If document is deleted, only creator can restore (R6 implies only creator can delete, so they should be able to restore too, 
    -- but strictly speaking R5 says "After an edit, the document must still belong to a team where the user is an editor".
    -- To be safe and align with R6 logic where only creator deletes, we allow editors to update non-deleted docs.
    -- If we want to allow restoration of deleted docs by the creator, we might need a specific policy or check.
    -- However, R6 says "Only the person who created a document can delete it". It doesn't explicitly forbid editors from restoring.
    -- But standard practice: only creator handles deletion lifecycle. Let's restrict updates to non-deleted docs for editors.
    deleted_at IS NULL
  )
);

-- R6: Only the person who created a document can delete it.
create policy "Only creators can delete documents"
on public.documents
for delete
using (created_by = auth.uid());
