-- Enable RLS
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

-- Helper function to check if user is suspended
create or replace function public.check_suspended()
returns boolean as $$
begin
  return not exists (
    select 1 from public.accounts a
    where a.user_id = auth.uid() and a.suspended = true
  );
end;
$$ language plpgsql security definer;

-- R6: Users can read their own account row. Nobody can change accounts through the app.
create policy "Users can read own account" on public.accounts for select
  using (user_id = auth.uid());

create policy "No changes to accounts" on public.accounts for all
  using (false);

-- R7: Anonymous visitors cannot see or change anything. (Implicitly handled by denying anon in other policies, but explicit here for clarity if needed, though 'using (auth.uid() is not null)' covers all authenticated. We will rely on specific policies for authenticated users and explicit 'deny' for anon where necessary or just ensure no policy matches anon.
-- Actually, standard Supabase practice: define policies for 'authenticated' role. If no policy matches 'anon', they get no access.
-- However, to be explicit about R7:
create policy "Deny anonymous on files" on public.files for all
  with check (false);
create policy "Deny anonymous on file_shares" on public.file_shares for all
  with check (false);
create policy "Deny anonymous on accounts" on public.accounts for all
  with check (false);

-- R1, R5: Owners can create files as themselves, read, rename (update name), delete own files. Suspended lose all.
-- Create
create policy "Owners can create files" on public.files for insert
  with check (auth.uid() = owner_id and public.check_suspended());

-- Select
create policy "Owners can read own files" on public.files for select
  using (owner_id = auth.uid() and public.check_suspended());

-- Update (rename only, as per R1 "rename" and R2 "rename" implies name change is the only update allowed for non-delete/edit scenarios in R1/R2 context, but R2 says "If share allows editing, they can also rename". R1 says owners can "rename". It doesn't explicitly say owners can change other fields like id (PK) or owner_id. We assume only 'name' is updatable by owner. R2 says share holders can rename if can_edit.
create policy "Owners can rename own files" on public.files for update
  using (owner_id = auth.uid() and public.check_suspended())
  with check (owner_id = auth.uid() and public.check_suspended());

-- Delete
create policy "Owners can delete own files" on public.files for delete
  using (owner_id = auth.uid() and public.check_suspended());

-- R2, R3: Shared file access.
-- Read
create policy "Users can read shared files" on public.files for select
  using (
    exists (
      select 1 from public.file_shares fs
      where fs.file_id = public.files.id
      and fs.shared_with = auth.uid()
      and (fs.expires_at is null or fs.expires_at > now())
      and public.check_suspended()
    )
  );

-- Update (Rename) for shared files
create policy "Users can rename shared files if can_edit" on public.files for update
  using (
    exists (
      select 1 from public.file_shares fs
      where fs.file_id = public.files.id
      and fs.shared_with = auth.uid()
      and (fs.expires_at is null or fs.expires_at > now())
      and fs.can_edit = true
      and public.check_suspended()
    )
  );

-- R3: Users shared with can never delete.
create policy "Users cannot delete shared files" on public.files for delete
  using (false);

-- R4: Shares management.
-- Owners manage shares of their files.
-- Insert (Create share)
create policy "Owners can create shares" on public.file_shares for insert
  with check (
    exists (
      select 1 from public.files f
      where f.id = file_shares.file_id and f.owner_id = auth.uid() and public.check_suspended()
    )
  );

-- Update (Change share settings)
create policy "Owners can update shares" on public.file_shares for update
  using (
    exists (
      select 1 from public.files f
      where f.id = file_shares.file_id and f.owner_id = auth.uid() and public.check_suspended()
    )
  );

-- Delete (Remove share)
create policy "Owners can delete shares" on public.file_shares for delete
  using (
    exists (
      select 1 from public.files f
      where f.id = file_shares.file_id and f.owner_id = auth.uid() and public.check_suspended()
    )
  );

-- Users see shares addressed to them.
-- Select
create policy "Users can see shares addressed to them" on public.file_shares for select
  using (shared_with = auth.uid() and public.check_suspended());

-- R8: Service role bypasses RLS.
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;

-- Ensure anonymous users have no grants (default is none, but revoke explicit if any exist from previous state, though policy 'with check (false)' handles it).
revoke all on public.files from anon;
revoke all on public.file_shares from anon;
revoke all on public.accounts from anon;
