alter table public.user_flag_overrides enable row level security;

-- Function to check if a config key is user-overridable
create function public.is_key_user_overridable(key_text text) returns boolean language sql stable as $$
  select exists (
    select 1 from public.app_config ac
    where ac.key = key_text and ac.user_overridable = true
  );
$$;

-- Policy R1: Anyone can read public config entries
create policy "Allow read access to public config entries"
  on public.app_config for select
  using (is_public = true);

-- Policy for non-public config: Only service role can read
create policy "Allow read access to non-public config entries (server-side only)"
  on public.app_config for select
  using (auth.role() = 'service_role');

-- Policy R2: Nobody can insert/update/delete app_config except service role
create policy "Disallow user modification of app_config"
  on public.app_config for all
  using (auth.role() = 'service_role');

-- Policy R5: Anonymous users cannot access overrides
create policy "Disallow anonymous access to user_flag_overrides"
  on public.user_flag_overrides for all
  using (auth.uid() is not null);

-- Policy R3 & R4: Signed-in users can only access their own overrides
create policy "Allow users to read their own overrides"
  on public.user_flag_overrides for select
  using (user_id = auth.uid());

-- Policy for insert/update/delete: Users can only modify their own overrides for public, user-overridable keys
create policy "Allow users to manage their own overrides for public, user-overridable keys"
  on public.user_flag_overrides for all
  using (
    user_id = auth.uid() 
    AND is_key_user_overridable(key)
  );

-- Policy R6: Service role has full access to overrides
create policy "Allow service role full access to user_flag_overrides"
  on public.user_flag_overrides for all
  using (auth.role() = 'service_role');
