-- Enable RLS on all tables
alter table public.restaurants enable row level security;
alter table public.restaurant_staff enable row level security;
alter table public.reservations enable row level security;

-- Helper function to check if user is staff at a specific restaurant
create or replace function public.is_staff_at(restaurant_id bigint, user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.restaurant_staff
    where restaurant_staff.restaurant_id = restaurant.id
    and restaurant_staff.user_id = user_id
  );
$$;

-- Policy R1: Signed-in users can see the list of restaurants
create policy "Users can view restaurants"
on public.restaurants
for select
using (auth.role() = 'authenticated');

-- Policy R1: Guests can see their own reservations
create policy "Users can view own reservations"
on public.reservations
for select
using (auth.uid() = user_id);

-- Policy R1: Restaurant staff can see every reservation at their restaurant
create policy "Staff can view restaurant reservations"
on public.reservations
for select
using (is_staff_at(restaurant_id, auth.uid()));

-- Policy R2: Guests can book (insert) only for a time in the future
create policy "Users can create future reservations"
on public.reservations
for insert
with check (
  auth.uid() = user_id
  and reserved_for > now()
);

-- Policy R3: Guests can cancel their own booked reservations while time is still in the future
create policy "Users can cancel own future reservations"
on public.reservations
for update
using (
  auth.uid() = user_id
  and status = 'booked'
  and reserved_for > now()
);

-- Policy R3: Prevent guests from changing anything else (implicit via other policies not granting update)
-- Explicitly deny guests from updating status to non-cancelled or changing other fields
create policy "Users cannot update reservations except cancel"
on public.reservations
for update
to authenticated
using (
  auth.uid() = user_id
  and status = 'booked'
  and reserved_for > now()
);

-- Policy R4: Staff can mark booked reservations as seated or no_show only after time has passed
create policy "Staff can update reservation status after time"
on public.reservations
for update
to authenticated
using (
  is_staff_at(restaurant_id, auth.uid())
  and status = 'booked'
  and reserved_for <= now()
  and new.status in ('seated', 'no_show')
);

-- Policy R4: Prevent staff from changing anything else (implicit via other policies)
-- Explicitly deny staff from updating status to 'booked' or changing other fields
create policy "Staff cannot update reservations except status change"
on public.reservations
for update
to authenticated
using (
  is_staff_at(restaurant_id, auth.uid())
  and status = 'booked'
  and reserved_for <= now()
  and new.status in ('seated', 'no_show')
);

-- Policy R5: Restaurants and staff lists cannot be changed through the app (no insert/update/delete)
-- Only service_role can modify these tables
revoke all on public.restaurants from authenticated, anon;
revoke all on public.restaurant_staff from authenticated, anon;

-- Policy R5: Reservations are never deleted (no delete policy for authenticated/anon)
-- Only service_role can delete (if needed for admin tasks, though spec says never deleted)
revoke delete on public.reservations from authenticated, anon;

-- Policy R6: Anonymous visitors cannot see or change anything
-- Already handled by 'to authenticated' in update policies and 'for select' policies requiring auth
-- Ensure anon has no permissions
revoke all on public.restaurants from anon;
revoke all on public.restaurant_staff from anon;
revoke all on public.reservations from anon;

-- Policy R7: Server-side code using the service role keeps full access
grant all on public.restaurants to service_role;
grant all on public.restaurant_staff to service_role;
grant all on public.reservations to service_role;
