-- Trigger function for accept_invite
create or replace function public.handle_accept_invite()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Check if user is signed in
  if auth.jwt() is null then
    raise exception 'User must be signed in to accept an invite';
  end if;

  -- Check if token exists
  if not exists (select 1 from public.invites where token = new.token) then
    raise exception 'Invalid invite token';
  end if;

  -- Fetch invite details
  declare
    v_org_id bigint;
    v_email text;
    v_role text;
    v_expires_at timestamptz;
    v_accepted_at timestamptz;
    v_invited_by uuid;
  begin
    select org_id, email, role, expires_at, accepted_at, invited_by
    into v_org_id, v_email, v_role, v_expires_at, v_accepted_at, v_invited_by
    from public.invites
    where token = new.token;

    -- Check if invite is already accepted
    if v_accepted_at is not null then
      raise exception 'Invite has already been accepted';
    end if;

    -- Check if invite has expired
    if now() > v_expires_at then
      raise exception 'Invite has expired';
    end if;

    -- Get caller's verified email from JWT
    declare
      v_caller_email text;
    begin
      select claim::text into v_caller_email
      from auth.jwt()
      where key = 'email';
    exception
      when others then
        raise exception 'Could not retrieve email from JWT';
    end;

    -- Normalize emails for comparison (case insensitive)
    if lower(v_email) != lower(v_caller_email) then
      raise exception 'Email does not match the invite';
    end if;

    -- Update invite to accepted
    update public.invites
    set accepted_at = now()
    where token = new.token;

    -- Insert new membership
    insert into public.org_members (org_id, user_id, role)
    values (v_org_id, auth.uid(), v_role);

    -- Return the org_id as requested by the RPC signature
    return new;
  end;
end;
$$;

-- Create the RPC function
create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id bigint;
begin
  -- Call the trigger function which handles all logic and returns the row
  perform public.handle_accept_invite()
  where token = p_token;

  -- Get the org_id from the updated invite
  select org_id into v_org_id
  from public.invites
  where token = p_token;

  return v_org_id;
exception
  when others then
    -- Re-raise the error if something went wrong
    raise;
end;
$$;

-- Grant execute on the RPC function to authenticated users
grant execute on function public.accept_invite(text) to authenticated;
