  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), (select role from public.invites where id = v_invite_id));

  return v_org_id;
exception
  when others then
    -- Rollback any partial changes if an error occurs (though transactions handle this automatically)
    rollback;
    raise;
