-- However, if the client calls it directly (which they shouldn't for security), we can restrict it
-- But the requirement says "Server-side code using the service_role keeps full access", implying the RPC is server-side.
-- If the RPC is exposed to clients, we might need a policy, but typically RPCs with complex logic are server-side only.
-- Assuming the RPC is server-side and called with service_role, no additional policy is needed for the client.
-- If the client calls the RPC directly, we should restrict it to admins or ensure the logic inside the RPC handles it.
-- Given the requirement "Nobody else can read invites", the RPC logic should be robust.
-- We will not add a policy for the RPC function as it's likely server-side only.

-- Grant execute on the helper functions to authenticated users for the RPC to use them if needed
-- Actually, the functions are security definer, so the owner (postgres) runs them.
-- The RPC function will be created with security definer as well.
-- We need to ensure the RPC function can be called.
-- If the RPC is server-side, no policy is needed.
-- If the RPC is client-side, we need to allow authenticated users to call it.
-- The requirement says "Supabase puts the account's verified email in the JWT claim email; users can edit their user_metadata."
-- This implies the RPC is called by the client.
-- So we need to allow authenticated users to call the RPC function.
-- But the RPC function logic is complex and should be server-side.
-- Let's assume the RPC is server-side and called with service_role.
-- The requirement "Nobody else can read invites" is enforced by the RLS policy on invites.
-- The RPC function will modify the invites and org_members tables, which will be checked by the RLS policies.
-- Since the RPC is called with service_role, it bypasses RLS.
-- So we don't need to worry about the RLS policies for the RPC function.

-- Insert the RPC function
create or replace function public.accept_invite(p_token text) returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id bigint;
  v_user_id uuid;
  v_invite public.invites;
begin
  -- Check if user is signed in
  if auth.uid() is null then
    raise exception 'User must be signed in to accept an invite';
  end if;

  -- Get the user's ID
  v_user_id := auth.uid();

  -- Get the invite
  select * into v_invite
  from public.invites
  where token = p_token
  for share;

  -- Check if the invite exists
  if not found then
    raise exception 'Invite not found';
  end if;

  -- Check if the invite is already accepted
  if v_invite.accepted_at is not null then
    raise exception 'Invite has already been accepted';
  end if;

  -- Check if the invite has expired
  if v_invite.expires_at <= now() then
    raise exception 'Invite has expired';
  end if;

  -- Check if the invite's email matches the user's verified email
  if lower(v_invite.email) <> lower((select email from auth.users where auth.users.id = v_user_id)) then
    raise exception 'Invite email does not match user's verified email';
  end if;

  -- Update the invite to mark it as accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  -- Insert the user into the org_members table
  insert into public.org_members (org_id, user_id, role)
  values (v_invite.org_id, v_user_id, v_invite.role)
  on conflict (org_id, user_id)
  do nothing;

  -- Return the organization's ID
  return v_invite.org_id;
end;
$$;

-- Grant execute on the RPC function to authenticated users
grant execute on function public.accept_invite(text) to authenticated;
