set search_path = public
as $$
  select exists (
    select 1 from public.project_members
    where project_members.project_id = p_project_id
    and project_members.user_id = p_user_id
    and project_members.role = 'maintainer'
  );
$$;

-- Helper function to check if user is the reporter of an issue
create or replace function public.is_issue_reporter(p_issue_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.issues
    where issues.id = p_issue_id
    and issues.reporter_id = p_user_id
  );
$$;

-- Helper function to check if user is the assignee of an issue
create or replace function public.is_issue_assignee(p_issue_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.issues
    where issues.id = p_issue_id
    and issues.assignee_id = p_user_id
  );
$$;

-- Helper function to check if user can see an issue
create or replace function public.can_see_issue(p_issue_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  declare
    v_project_id bigint;
    v_is_maintainer boolean;
    v_is_reporter boolean;
    v_is_assignee boolean;
  begin
    -- Get project ID
    select project_id into v_project_id from public.issues where id = p_issue_id;

    -- Check visibility conditions
    v_is_maintainer := public.is_project_maintainer(v_project_id, p_user_id);
    v_is_reporter := public.is_issue_reporter(p_issue_id, p_user_id);
    v_is_assignee := public.is_issue_assignee(p_issue_id, p_user_id);

    -- Confidential issues: only maintainers, reporter, or assignee can see
    if (select is_confidential from public.issues where id = p_issue_id) then
      return v_is_maintainer or v_is_reporter or v_is_assignee;
    else
      -- Non-confidential issues: any member of the project can see
      return public.is_project_member(v_project_id, p_user_id);
    end if;
  end;
$$;

-- Helper function to check if user can update an issue
create or replace function public.can_update_issue(p_issue_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  declare
    v_project_id bigint;
    v_is_maintainer boolean;
    v_is_reporter boolean;
    v_is_assignee boolean;
    v_is_developer boolean;
  begin
    -- Get project ID
    select project_id into v_project_id from public.issues where id = p_issue_id;

    -- Check membership
    if not public.is_project_member(v_project_id, p_user_id) then
      return false;
    end if;

    -- Check roles
    v_is_maintainer := public.is_project_maintainer(v_project_id, p_user_id);
    v_is_reporter := public.is_issue_reporter(p_issue_id, p_user_id);
    v_is_assignee := public.is_issue_assignee(p_issue_id, p_user_id);
    v_is_developer := exists (
      select 1 from public.project_members
      where project_members.project_id = v_project_id
      and project_members.user_id = p_user_id
      and project_members.role = 'developer'
    );

    -- Only maintainers can update, except reporters can update their own issues if they are also developers/maintainers
    -- Actually, rule R4 says: "Developers and maintainers can update the issues they can see. Only maintainers can make an issue confidential or not confidential. Reporters cannot update issues."
    -- So reporters cannot update ANY issues.
    if v_is_reporter and not v_is_maintainer and not v_is_developer then
      return false;
    end if;

    -- If reporter is also a developer or maintainer, they can update
    if v_is_reporter and (v_is_maintainer or v_is_developer) then
      return true;
    end if;

    -- Developers and maintainers can update issues they can see
    return v_is_maintainer or v_is_developer;
  end;
$$;

-- Policy R6: Anonymous visitors cannot see or change anything
create policy "Anonymous users cannot access any data" on public.projects
for all using (false);

create policy "Anonymous users cannot access any data" on public.project_members
for all using (false);

create policy "Anonymous users cannot access any data" on public.issues
for all using (false);

-- Policy R7: Service role keeps full access
create policy "Service role has full access" on public.projects
for all using (true);

create policy "Service role has full access" on public.project_members
for all using (true);

create policy "Service role has full access" on public.issues
for all using (true);

-- Policy R1: Members can see their projects
create policy "Members can see their projects" on public.projects
for select using (public.is_project_member(id, auth.uid()));

-- Policy R1: Members can see every member of those projects
create policy "Members can see project members" on public.project_members
for select using (public.is_project_member(project_id, auth.uid()));

-- Policy R2: Members can see every non-confidential issue in their projects
create policy "Members can see non-confidential issues" on public.issues
for select using (public.can_see_issue(id, auth.uid()));

-- Policy R3: Members can file issues in their projects as the reporter
create policy "Members can create issues in their projects" on public.issues
for insert with check (
  public.is_project_member(project_id, auth.uid())
);

-- Policy R4: Developers and maintainers can update the issues they can see
create policy "Developers and maintainers can update issues they can see" on public.issues
for update using (public.can_update_issue(id, auth.uid()))
with check (public.can_update_issue(id, auth.uid()));

-- Policy R4: Only maintainers can change confidentiality status (enforced by application logic mostly, but we can add a check if needed)
-- The update policy above already restricts who can update. The application should ensure only maintainers set is_confidential.
-- However, to be extra safe, we could add a specific check, but the general update policy covers it.

-- Policy R5: Issues are never deleted
drop policy if exists "Members can delete issues" on public.issues;
create policy "Issues cannot be deleted" on public.issues
for delete using (false);

-- Policy R5: Nobody can change projects or memberships through the app
drop policy if exists "Members can update projects" on public.projects;
drop policy if exists "Members can update project_members" on public.project_members;

create policy "Projects cannot be updated" on public.projects
for update using (false);

create policy "Project members cannot be updated" on public.project_members
for update using (false);

-- Grant service_role full access explicitly (though the policy above handles it, explicit grants are good practice)
grant all on all tables in schema public to service_role;
grant all on all functions in schema public to service_role;

-- Ensure anonymous users have no permissions (default, but explicit for clarity)
revoke all on public.projects from anon;
revoke all on public.project_members from anon;
revoke all on public.issues from anon;
revoke all on public.projects from authenticated; -- Will be granted via policies
revoke all on public.project_members from authenticated; -- Will be granted via policies
revoke all on public.issues from authenticated; -- Will be granted via policies
