-- Create the dispense RPC function
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Check if caller is a pharmacist
  if not public.is_pharmacist() then
    raise exception 'Only pharmacists can dispense medications';
  end if;

  -- Check if prescription exists
  if not exists (select 1 from public.prescriptions where id = p_prescription_id) then
    raise exception 'Prescription not found';
  end if;

  -- Check if prescription is expired
  if (select expires_at from public.prescriptions where id = p_prescription_id) < now() then
    raise exception 'Prescription has expired';
  end if;

  -- Check if prescription has refills left
  if (select refills_left from public.prescriptions where id = p_prescription_id) <= 0 then
    raise exception 'No refills left';
  end if;

  -- Check if prescription is the caller's own (pharmacists shouldn't dispense their own prescriptions)
  if (select patient_id from public.prescriptions where id = p_prescription_id) = auth.uid() then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

  -- Perform the dispense
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, auth.uid(), now());

  return (select refills_left from public.prescriptions where id = p_prescription_id);
end;
$$;
