-- ==========================================
-- 1. Helper Functions & Triggers
-- ==========================================

-- Function to handle the dispense logic with business rules
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_prescription record;
  v_pharmacist_id uuid;
  v_refills_left integer;
begin
  -- Fetch prescription details
  select p.*, u.id into v_prescription
  from public.prescriptions p
  join auth.users u on u.id = p.patient_id
  where p.id = p_prescription_id;

  -- Check if prescription exists
  if not found then
    raise exception 'Prescription not found';
  end if;

  -- Get current user (pharmacist)
  v_pharmacist_id := auth.uid();

  -- Rule 4: Check if caller is a pharmacist
  if not exists (select 1 from public.pharmacists where user_id = v_pharmacist_id) then
    raise exception 'Caller must be a pharmacist';
  end if;

  -- Rule 4: Check if prescription is the caller's own
  if v_prescription.patient_id = v_pharmacist_id then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

  -- Rule 4: Check if prescription has expired
  if v_prescription.expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  -- Rule 4: Check if refills left > 0
  if v_prescription.refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  -- Decrement refills
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  -- Record dispense
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  -- Return updated refills left
  select refills_left into v_refills_left
  from public.prescriptions
  where id = p_prescription_id;

  return v_refills_left;
end;
$$;

