    raise exception 'User has already signed this envelope';
  end if;

  -- Get current sign order for this user
  select sign_order into v_current_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if earlier signers have signed
  if exists (
    select 1 from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
    and r.sign_order < v_current_order
    and r.signed_at is null
  ) then
    raise exception 'Previous signers have not yet signed';
  end if;

  -- Record signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  -- Check if all recipients have signed
  if public.all_recipients_signed(p_envelope_id) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
end;
$$;

