  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Check if all previous signers have signed
  if not public.is_next_signer(p_envelope_id, v_user_id) then
    raise exception 'Previous signers have not signed yet';
  end if;

  -- Record signature
  insert into public.envelope_recipients (envelope_id, user_id, sign_order, signed_at)
  values (p_envelope_id, v_user_id, (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_user_id), now());

  -- Check if all recipients have signed now
  if public.all_recipients_signed(p_envelope_id) then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
