ALTER TABLE public.devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.device_commands ENABLE ROW LEVEL SECURITY;

-- Helper function to check if user is an IT admin for a given org
CREATE OR REPLACE FUNCTION public.is_org_admin(p_org_id bigint, p_user_id uuid)
RETURNS boolean AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.org_admins
    WHERE org_admins.org_id = p_org_id
      AND org_admins.user_id = p_user_id
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Helper function to check if user is an employee (assigned a device)
CREATE OR REPLACE FUNCTION public.is_device_owner(p_device_id bigint, p_user_id uuid)
RETURNS boolean AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.devices
    WHERE devices.id = p_device_id
      AND devices.assigned_to = p_user_id
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Policy for org_admins: Only admins can see their own records
CREATE POLICY org_admins_select_policy ON public.org_admins
  FOR SELECT USING (
    auth.jwt()->>'role' = 'authenticated' OR auth.jwt()->>'role' = 'service_role'
    AND EXISTS (
      SELECT 1 FROM public.org_admins admin
      WHERE admin.org_id = org_admins.org_id
        AND admin.user_id = auth.uid()
    )
  );

-- Policy for devices:
-- 1. Authenticated users see devices assigned to them
-- 2. Authenticated users see devices in orgs where they are admins
-- 3. Service role sees all
CREATE POLICY devices_select_policy ON public.devices
  FOR SELECT USING (
    auth.jwt()->>'role' = 'service_role'
    OR (
      auth.jwt()->>'role' = 'authenticated'
      AND (
        assigned_to = auth.uid()
        OR is_org_admin(org_id, auth.uid())
      )
    )
  );

-- Policy for device_commands:
-- 1. Authenticated users see commands for devices they own
-- 2. Authenticated users see commands for devices in orgs where they are admins
-- 3. Service role sees all
CREATE POLICY device_commands_select_policy ON public.device_commands
  FOR SELECT USING (
    auth.jwt()->>'role' = 'service_role'
    OR (
      auth.jwt()->>'role' = 'authenticated'
      AND (
        device_id IN (SELECT id FROM public.devices WHERE assigned_to = auth.uid())
        OR device_id IN (SELECT id FROM public.devices WHERE org_id IN (SELECT org_id FROM public.org_admins WHERE user_id = auth.uid()))
      )
    )
  );

-- Policy for device_commands insert (Issue Commands):
-- 1. Service role can insert anything
-- 2. Authenticated users (admins) can insert to any device in their org
-- 3. Authenticated users (employees) can insert to their own device ONLY with 'locate' or 'lock'
CREATE POLICY device_commands_insert_policy ON public.device_commands
  FOR INSERT WITH CHECK (
    auth.jwt()->>'role' = 'service_role'
    OR (
      auth.jwt()->>'role' = 'authenticated'
      AND (
        -- Admin path: Full access to org devices
        auth.uid() IN (SELECT user_id FROM public.org_admins WHERE org_id = (SELECT org_id FROM public.devices WHERE id = device_id))
        OR 
        -- Employee path: Only own device, and only non-wipe commands
        (
          assigned_to = auth.uid()
          AND command NOT IN ('wipe')
        )
      )
    )
  );

-- Policy for device_commands update: Nobody can update
CREATE POLICY device_commands_update_policy ON public.device_commands
  FOR UPDATE TO NONE;

-- Policy for device_commands delete: Nobody can delete
CREATE POLICY device_commands_delete_policy ON public.device_commands
  FOR DELETE TO NONE;

-- Policy for devices update: Nobody can update devices via app
CREATE POLICY devices_update_policy ON public.devices
  FOR UPDATE TO NONE;

-- Policy for devices delete: Nobody can delete devices via app
CREATE POLICY devices_delete_policy ON public.devices
  FOR DELETE TO NONE;

-- Policy for org_admins update: Nobody can update admins via app
CREATE POLICY org_admins_update_policy ON public.org_admins
  FOR UPDATE TO NONE;

-- Policy for org_admins delete: Nobody can delete admins via app
CREATE POLICY org_admins_delete_policy ON public.org_admins
  FOR DELETE TO NONE;

-- Ensure service role has full access explicitly (though policies handle it, grants reinforce)
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
