-- Enable Row Level Security on all tables
alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

-- Helper function to check if user is a reviewer
create or replace function public.is_reviewer()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
select exists (
  select 1 from public.reviewers where user_id = auth.uid()
);
$$;

-- ============================================================================
-- reviewers table policies
-- ============================================================================

-- R5: Nobody can insert/update/delete reviewers via app. Only service_role can manage.
create policy "disable_insert" on public.reviewers for insert
with check (false);

create policy "disable_update" on public.reviewers for update
using (false);

create policy "disable_delete" on public.reviewers for delete
using (false);

-- Allow service_role to manage reviewers (for the server tool)
grant all on public.reviewers to service_role;

-- ============================================================================
-- proposals table policies
-- ============================================================================

-- R1: Speakers see own proposals. Reviewers see all.
create policy "speakers_see_own" on public.proposals for select
using (speaker_id = auth.uid());

create policy "reviewers_see_all" on public.proposals for select
using (is_reviewer());

-- R6: Anonymous cannot see anything
revoke all on public.proposals from anon;

-- R2: Signed-in users can submit proposals as themselves (status defaults to 'submitted')
create policy "speakers_submit" on public.proposals for insert
with check (auth.uid() = speaker_id);

-- R2: Edit own proposals only while undecided (status not in 'accepted', 'rejected')
create policy "speakers_edit_undecided" on public.proposals for update
using (
  speaker_id = auth.uid() 
  and status not in ('accepted', 'rejected')
);

-- R2: Service role can manage all proposals (for state transitions)
grant all on public.proposals to service_role;

-- ============================================================================
-- reviews table policies
-- ============================================================================

-- R3: Reviewers review undecided proposals once, never their own
-- R3: Edit own reviews while proposal is undecided
-- R3: Insert condition: reviewer != speaker AND status != 'accepted' AND status != 'rejected'
-- Note: The "once" constraint is typically handled by application logic or unique constraints + upsert logic,
-- but for RLS we focus on visibility and modification rights based on status.
-- Since primary key is (proposal_id, reviewer_id), RLS doesn't prevent duplicate inserts 
-- unless we add a check constraint or rely on unique violation handling at app level.
-- We will enforce the "not own proposal" and "proposal status" rules here.

create policy "reviewers_submit_foreign" on public.reviews for insert
with check (
  reviewer_id != speaker_id 
  and (select status from public.proposals p where p.id = proposal_id) not in ('accepted', 'rejected')
);

-- R3: Edit own reviews while proposal is undecided
create policy "reviewers_edit_own_undecided" on public.reviews for update
using (
  reviewer_id = auth.uid()
  and (select status from public.proposals p where p.id = proposal_id) not in ('accepted', 'rejected')
);

-- R3: Delete own reviews while proposal is undecided
create policy "reviewers_delete_own_undecided" on public.reviews for delete
using (
  reviewer_id = auth.uid()
  and (select status from public.proposals p where p.id = proposal_id) not in ('accepted', 'rejected')
);

-- R4: Reviewers see only their own reviews
create policy "reviewers_see_own" on public.reviews for select
using (reviewer_id = auth.uid());

-- R4: Speakers can see reviews of their own proposals ONLY if status is 'accepted' or 'rejected'
create policy "speakers_see_reviews_on_decision" on public.reviews for select
using (
  (select speaker_id from public.proposals p where p.id = proposal_id) = auth.uid()
  and (select status from public.proposals p where p.id = proposal_id) in ('accepted', 'rejected')
);

-- R6: Anonymous cannot see or change anything
revoke all on public.reviews from anon;

-- Allow service_role to manage all reviews (for state transitions or bulk ops if needed)
grant all on public.reviews to service_role;
