alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

-- Helper function to check if user is a reviewer
create or replace function public.is_reviewer()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
select exists (
  select 1 from public.reviewers where user_id = auth.uid()
);
$$;

-- ============================================================================
-- reviewers table policies
-- ============================================================================

-- R5: Nobody can insert/update/delete reviewers via app. Only service_role can manage.
create policy "disable_insert" on public.reviewers for insert
with check (false);

create policy "disable_update" on public.reviewers for update
using (false);

create policy "disable_delete" on public.reviewers for delete
using (false);

-- Allow service_role to manage reviewers (for the server tool)
grant all on public.reviewers to service_role;

-- ============================================================================
-- proposals table policies
-- ============================================================================

-- R1: Speakers see their own; reviewers see all.
create policy "speakers_see_own" on public.proposals for select
using (speaker_id = auth.uid());

create policy "reviewers_see_all" on public.proposals for select
using (true);

-- R2: Signed-in users can insert as themselves.
create policy "speakers_insert" on public.proposals for insert
with check (auth.uid() = speaker_id);

-- R2: Signed-in users can update own proposals while undecided (status != 'accepted' and status != 'rejected').
create policy "speakers_update_own_undecided" on public.proposals for update
using (
  speaker_id = auth.uid() 
  and status not in ('accepted', 'rejected')
);

-- R6: Anonymous users cannot see or change anything. (Implicitly handled by lack of policies for anon, but explicit deny is safer if anon has generic access elsewhere, though Supabase default is no access. We ensure no other policies exist for anon).
-- Explicitly ensure anon cannot see proposals via a negative check if needed, but standard supabase behavior is no access for anon without a policy.
-- However, to be explicit about R6:
create policy "anon_no_access" on public.proposals for all
using (false) with check (false);

-- ============================================================================
-- reviews table policies
-- ============================================================================

-- R3 & R4: Reviewers can review undecided proposals (once).
-- They cannot review their own proposals.
-- They must be a reviewer (checked by R3, implied by is_reviewer() in policy or trigger).
-- Since we can't easily count "once" in a simple policy without state, we rely on the unique constraint (proposal_id, reviewer_id) and the logic that they insert as themselves.
-- The policy allows the attempt; the DB constraint prevents duplicates.

create policy "reviewers_insert" on public.reviews for insert
using (
  auth.uid() = reviewer_id
  and is_reviewer()
  and not exists (
    select 1 from public.reviews 
    where proposal_id = proposals.id 
    and reviewer_id = auth.uid()
  )
);

-- R3 & R4: Reviewers can update their own reviews while the proposal is undecided.
create policy "reviewers_update_own_undecided" on public.reviews for update
using (
  reviewer_id = auth.uid()
  and is_reviewer()
  and p.status not in ('accepted', 'rejected')
);

-- R4: Reviewers see only their own reviews.
create policy "reviewers_see_own" on public.reviews for select
using (reviewer_id = auth.uid());

-- R4: Speakers can see reviews of their own proposals ONLY if a decision has been made (status in 'accepted' or 'rejected').
create policy "speakers_see_own_reviews_after_decision" on public.reviews for select
using (
  p.speaker_id = auth.uid()
  and p.status in ('accepted', 'rejected')
);

-- R6: Anonymous users cannot see or change anything.
create policy "anon_no_access_reviews" on public.reviews for all
using (false) with check (false);

-- ============================================================================
-- Triggers for data integrity (Speaker ID consistency)
-- Note: auth.uid() is only available in the trigger context if we don't use security definer that strips it, 
-- but for inserts we generally rely on default auth.uid() in the application or a trigger that sets it.
-- The schema says speaker_id default auth.uid(). 
-- However, if a user bypasses defaults, we might want to enforce speaker_id = auth.uid() on insert.
-- The default ensures it, but let's add a trigger to be safe against malformed inserts.
-- Actually, the requirement R2 says "submit proposals as themselves". 
-- If the app does .insert({ speaker_id: userId }), the default won't run.
-- We should enforce speaker_id = auth.uid() on insert.
-- But wait, the schema has `default auth.uid()`. If the app overrides this, we want to catch it? 
-- Usually, apps respect the default. Let's assume the app sets speaker_id correctly.
-- However, to strictly enforce "as themselves" even if the app forgets the field:
-- We need a trigger. But triggers don't run for default values automatically.
-- If the app sends `{ title: "..." }`, default runs. If app sends `{ title: "...", speaker_id: "..." }`, default is ignored.
-- To enforce R2 strictly: speaker_id must match auth.uid() on insert.
-- We can use a trigger that validates this.

create or replace function public.enforce_speaker_ownership()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.speaker_id is not null and new.speaker_id <> auth.uid() then
    raise foreign_key_violation using message = 'Speaker ID must match the authenticated user';
  end if;
  return new;
end;
$$;

create trigger trigger_enforce_speaker_ownership
  before insert on public.proposals
  for each row
  execute function public.enforce_speaker_ownership();

-- ============================================================================
-- Grants for Service Role
-- ============================================================================
grant all on public.reviewers to service_role;
grant all on public.proposals to service_role;
grant all on public.reviews to service_role;

-- Revoke all from anon and authenticated explicitly to ensure R6 (if any generic grants exist)
-- Supabase default is no access, but we ensure revokes are present if we had grants.
-- Since we created specific policies, generic grants might not be needed, but revoking ensures cleanliness.
revoke all on public.reviewers from anon;
revoke all on public.proposals from anon;
revoke all on public.reviews from anon;
revoke all on public.reviewers from authenticated;
revoke all on public.proposals from authenticated;
revoke all on public.reviews from authenticated;
-- Keep authenticated user having ability to call functions/trigger logic implicitly, but data access is policy controlled.
-- Note: authenticated role has no direct row access without policies, which we defined above.
```

```sql
-- Enable RLS on all tables
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- Helper function to check if a user is an HOA admin
create or replace function public.is_hoa_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.hoa_admins where user_id = auth.uid());
$$;

-- Helper function to check if a user is a resident of a specific unit
create or replace function public.is_resident_of_unit(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.residents where unit_id = p_unit_id and user_id = auth.uid());
$$;

-- Helper function to count active permits for a unit
create or replace function public.count_active_permits_for_unit(p_unit_id bigint)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*)
  from public.permits
  where unit_id = p_unit_id
    and revoked = false
    and valid_until >= current_date;
$$;

-- Helper function to check if a permit is valid (not revoked and within date range)
create or replace function public.is_permit_valid(p_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select (revoked = false) and (valid_until >= current_date)
  from public.permits
  where id = p_id;
$$;

-- Policy R5: Anonymous users cannot see or change anything
create policy "Anonymous users cannot see or change anything" on public.residents
  for all
  to anon
  using (false)
  with check (false);

create policy "Anonymous users cannot see or change anything" on public.hoa_admins
  for all
  to anon
  using (false)
  with check (false);

create policy "Anonymous users cannot see or change anything" on public.permits
  for all
  to anon
  using (false)
  with check (false);

-- Policy R5: Nobody can change residents or HOA admins through the app (except service_role)
create policy "Residents table immutable for app users" on public.residents
  for all
  to authenticated
  using (false)
  with check (false);

create policy "HOA admins table immutable for app users" on public.hoa_admins
  for all
  to authenticated
  using (false)
  with check (false);

-- Policy R6: Service role has full access
create policy "Service role has full access" on public.residents
  for all
  to service_role
  using (true)
  with check (true);

create policy "Service role has full access" on public.hoa_admins
  for all
  to service_role
  using (true)
  with check (true);

create policy "Service role has full access" on public.permits
  for all
  to service_role
  using (true)
  with check (true);

-- Policy R1 & R2: Residents can see their own residence rows and the permits of their unit
create policy "Residents can see their own residence rows" on public.residents
  for select
  to authenticated
  using (public.is_resident_of_unit(unit_id));

create policy "Residents can see permits of their unit" on public.permits
  for select
  to authenticated
  using (public.is_resident_of_unit(unit_id));

-- Policy R1: HOA admins can see every permit
create policy "HOA admins can see every permit" on public.permits
  for select
  to authenticated
  using (public.is_hoa_admin());

-- Policy R2: Residents can add permits for their own unit while it has fewer than 2 active permits
create policy "Residents can add permits for their unit if under limit" on public.permits
  for insert
  to authenticated
  with check (
    public.is_resident_of_unit(unit_id)
    and public.count_active_permits_for_unit(unit_id) < 2
    and (valid_until - current_date) <= interval '365 days'
  );

-- Policy R2: Prevent inserting revoked permits or permits with invalid dates (enforced by app logic mostly, but DB check helps)
create policy "Prevent invalid permit inserts" on public.permits
  for insert
  to authenticated
  with check (
    revoked = false
    and valid_until >= current_date
  );

-- Policy R3: Residents can update plate on their unit's permits
create policy "Residents can update plate on their unit's permits" on public.permits
  for update
  to authenticated
  using (public.is_resident_of_unit(unit_id))
  with check (
    public.is_resident_of_unit(unit_id)
    and (coalesce(new.plate, old.plate) is not null)
  );

-- Policy R3: Prevent residents from changing validity, revoking, or un-revoking
create policy "Residents cannot change validity or revocation status" on public.permits
  for update
  to authenticated
  using (public.is_resident_of_unit(unit_id))
  with check (
    public.is_resident_of_unit(unit_id)
    and (new.valid_until = old.valid_until)
    and (new.revoked = old.revoked)
  );

-- Policy R4: HOA admins can revoke any permit
create policy "HOA admins can revoke any permit" on public.permits
  for update
  to authenticated
  using (public.is_hoa_admin())
  with check (
    public.is_hoa_admin()
    and (new.revoked = true or new.revoked = old.revoked)
  );

-- Policy R4: Nobody can un-revoke a permit (global constraint)
create policy "No one can un-revoke a permit" on public.permits
  for update
  to authenticated
  using (true)
  with check (
    (new.revoked = true) or (new.revoked = old.revoked)
  );

-- Policy R4: Permits are never deleted (default behavior, but explicit policy for clarity if needed, though RLS doesn't prevent delete by default unless specified)
-- Since RLS doesn't prevent delete by default, we add a policy to prevent deletes for authenticated users
create policy "Permits cannot be deleted by app users" on public.permits
  for delete
  to authenticated
  using (false)
  with check (false);

-- Policy R4: HOA admins also cannot delete permits (only revoke)
create policy "HOA admins cannot delete permits" on public.permits
  for delete
  to authenticated
  using (public.is_hoa_admin())
  with check (false);

-- Policy R5: Nobody can change residents or HOA admins (already covered by immutable policies above)
-- Ensure service_role can still delete if needed for cleanup, but requirement says "Permits are never deleted"
-- So we rely on the delete policies above.

-- Grant necessary permissions for functions
grant execute on function public.is_hoa_admin() to authenticated, service_role;
grant execute on function public.is_resident_of_unit(bigint) to authenticated, service_role;
grant execute on function public.count_active_permits_for_unit(bigint) to authenticated, service_role;
grant execute on function public.is_permit_valid(bigint) to authenticated, service_role;
